#[test]
fn sqlite_snapshot_semio_document_rejects_cycles_ownership_variant_shapes_and_budgets(){let original=project(&fixture());for mutation in 0..6{let mut db=original.clone();match mutation{0=>db.table_mut("semio_document_style").unwrap().rows[0].values[5]=SqliteValue::Integer(2),1=>db.table_mut("semio_document_quote").unwrap().rows[0].values[1]=SqliteValue::Integer(1),2=>db.table_mut("semio_document_member").unwrap().rows[0].values[3]=SqliteValue::Integer(999),3=>db.table_mut("semio_document_heading").unwrap().rows[0].values[1]=SqliteValue::Integer(256),4=>db.table_mut("semio_document_run").unwrap().rows[0].values[4]=SqliteValue::Integer(2),_=>{db.table_mut("semio_document_image_block").unwrap().rows[0].values[1]=SqliteValue::Integer(999);}}assert!(restore(&db).is_err());}let limits=SqliteDatabaseLimits{max_value_bytes:1,max_rows:1,..SqliteDatabaseLimits::default()};assert!(fixture().to_sqlite_database(&mut SqliteSnapshotControl::new(&mut |_|true,limits)).is_err());assert!(SemioDocumentSnapshot::from_sqlite_database(&original,&mut SqliteSnapshotControl::new(&mut |_|true,limits)).is_err());assert!(fixture().to_sqlite_database(&mut SqliteSnapshotControl::new(&mut |_|false,SqliteDatabaseLimits::default())).is_err());}
#[test]
fn sqlite_snapshot_semio_document_independent_sqlite_style_image_run_queries_and_edit(){use std::io::Write;use std::process::{Command,Stdio};let bytes=export_sqlite_database(&project(&fixture()),SqliteDatabaseLimits::default(),&mut |_|true).unwrap();let script="import{Database}from'bun:sqlite';const db=Database.deserialize(new Uint8Array(await Bun.stdin.arrayBuffer()));if(db.query('PRAGMA integrity_check').get().integrity_check!=='ok'||db.query('PRAGMA foreign_key_check').all().length)throw Error('integrity');const r=db.query('SELECT bold,italic,underline,font FROM semio_document_run ORDER BY id').get();if(r.bold!==1||r.italic!==1||r.underline!==1||r.font!=='')throw Error('run fields');const i=db.query('SELECT native_id,length(bytes) AS size FROM semio_document_image JOIN semio_document_image_block ON image_id=semio_document_image.id').get();if(i.size!==3)throw Error('image FK');db.query(\"UPDATE semio_document_run SET text='independently edited' WHERE id=1\").run();await Bun.write(Bun.stdout,db.serialize());db.close();";let mut child=Command::new("bun").args(["-e",script]).stdin(Stdio::piped()).stdout(Stdio::piped()).stderr(Stdio::piped()).spawn().unwrap();child.stdin.take().unwrap().write_all(&bytes).unwrap();let out=child.wait_with_output().unwrap();assert!(out.status.success(),"{}",String::from_utf8_lossy(&out.stderr));let r=restore(&import_sqlite_database(&out.stdout,SqliteDatabaseLimits::default(),&mut |_|true).unwrap()).unwrap();let mut expected=fixture();if let DocBlock::Paragraph{runs,..}=&mut expected.blocks[0]{runs[0].text="independently edited".into();}assert_eq!(r,expected);}

